@chiraggmodi For the original problem you could hack the `afterFit` function to set the `minSize.width` and the `width` of the legend to a fixed value.

[codepen example](https://codepen.io/anon/pen/LOBPMV)
N.B. I changed the div-classes to div-IDs, as they were used as unique identifiers.

![issue-4982-same-width-doughnut-chart](https://user-images.githubusercontent.com/33193571/33228986-18f8034c-d1c6-11e7-877b-8ac2d83e968e.png)

```javascript
var charts = [];

/**
 * set fixed width/height option for the legend
 */
Chart.Legend.prototype.afterFit = function() {
    var opts = this.options;
    if (typeof this.options.width === 'number') {
        this.minSize.width = opts.width;
        this.width = opts.width;
    }
    if (typeof this.options.height === 'number') {
        this.minSize.height = opts.height;
        this.height = opts.height;
    }
}

/**
 * Equalize legend width/height for all charts
 * uses maximum width/height
 */
function equalizeLegendWidth() {
    var maxLegendSize = 0;
    charts.forEach(function(chart) {
        var legend = chart.legend;
        var size = legend.isHorizontal()
            ? legend.height
            : legend.width;
        if (size > maxLegendSize) {
            maxLegendSize = size;
        }
    });
    if (maxLegendSize > 0) {
        charts.forEach(function(chart) {
           var legend = chart.legend;

           if (legend.isHorizontal()) {
                chart.legend.options.height = maxLegendSize;
            } else {
                chart.legend.options.width = maxLegendSize;
            }
            chart.update();
        });
    }
}

/**
 * get the preferred legend position
 */
function getLegendPosition() {
    return ($(window).width() < 1024)
        ? 'bottom'
        : 'right';
}

/**
 * update charts
 */
function updateCharts() {
    if (charts.length > 0) {
        legendPosition = getLegendPosition();
        if (charts[0].legend.options.position !== legendPosition) {
            buildCharts();
        }
    }
}

/**
 * build charts
 */
function buildCharts() {
    var containerId = 'chartdata';
    var numcharts = $('[id^=' + containerId + ']').length;
    var legendPosition = getLegendPosition();

    // reset charts
    while(charts.length) {
        charts.pop().destroy();
    }
    // rebuild charts
    for (var i = 1; i <= numcharts; i += 1) {
        var chartId = 'mychart' + i;
        var chartDataId = 'chartdata' + i;
        charts.push(constructChart(legendPosition, chartId, chartDataId));
    }
    equalizeLegendWidth();
}

function constructChart(legendPosition, chartId, chartDataId) {
    var backgroundColor = [];
    var labels = [];
    var data = [];
    var ctx = document.getElementById(chartId).getContext("2d");

    $('#' + chartDataId + ' span').each(function(ignore, el) {
        var elData = el.dataset;
        labels.push(elData.title);
        backgroundColor.push(elData.color);
        data.push(elData.value);
    });

    var config = {
        type: 'doughnut',
        data: {
            datasets: [{
                data: data,
                backgroundColor: backgroundColor,
            }],
            labels: labels
        },
        options: {
            responsive: false,
            maintainAspectRatio: true,
            legend: {
                position: legendPosition,
            },
            animation: {
                animateScale: true,
                animateRotate: true
            },
        },
    };
    newChart = new Chart(ctx, config);
    return newChart;
}

$(function() {
    buildCharts();
    $(window).on('resize', updateCharts);
});
```
Edit: added `updateCharts` to only rebuild charts when the legend position changed, or only update the legend position and recalculate update like shown below.

```javascript
/**
 * update charts
 */
function updateCharts() {
    if (charts.length > 0) {
        legendPosition = getLegendPosition();
        if (charts[0].legend.options.position !== legendPosition) {
            charts.forEach(function(chart) {
                chart.options.legend.position = legendPosition;
                delete chart.options.legend.width;
                delete chart.options.legend.height;
                chart.update();
            });
            equalizeLegendWidth();
        }
    }
}
```

